HQ.reg("extra","grammar-ru",{"target":"ru","ui":["he","en"],"lessons":[{"id":"alphabet_stress","level":"A1","title":{"he":"קריאת קירילית והטעמה","en":"Reading Cyrillic and stress"},"text":{"he":["ברוסית 33 אותיות. כותבים משמאל לימין, ויש אותיות גדולות וקטנות (А а, Б б). רוב המילים נקראות כמעט כפי שהן נכתבות.","חלק מהאותיות דומות לאותיות לטיניות, אבל נשמעות אחרת: В = ו, Н = נ, Р = ר, С = ס, Х = ח, У = או. למשל, нос נקרא \"נוס\" (אף), ו-сок נקרא \"סוק\" (מיץ).","בניגוד לעברית, כל התנועות נכתבות. ארבע תנועות מוסיפות צליל י לפניהן: я = יא, ю = יו, ё = יו, е = יֶ. לתנועה ы אין מקבילה בעברית: זו \"אי\" עמוקה, כשהלשון נסוגה לאחור. הסימן ь (סימן רך) אינו נשמע בעצמו — הוא מרכך את העיצור שלפניו.","בכל מילה יש הברה מוטעמת אחת, והיא יכולה ליפול בכל מקום — אין כלל קבוע. בספרי לימוד מסמנים אותה בקו מעל התנועה: молоко́ (חלב). בעיתונים ובשלטים אין סימון, ולכן לומדים את ההטעמה יחד עם המילה. האות ё תמיד מוטעמת.","ההטעמה משנה את הצליל: о שאינה מוטעמת נשמעת כמו а, ו-е או я שאינן מוטעמות נשמעות כמעט כמו и. לכן молоко́ נשמע \"מלקו\", ו-спаси́бо (תודה) נשמע \"ספסיבא\"."],"en":["Russian has 33 letters. Like English, it is written left to right, with capital and small letters (А а, Б б). Most words are read almost exactly as they are written.","Watch out for \"false friends\" — letters that look Latin but sound different: В = v, Н = n, Р = r (rolled), С = s, Х = kh (as in Scottish loch), У = oo. So нос reads \"nos\" (nose) and сок reads \"sok\" (juice).","Four vowels add a \"y\" sound in front: я = ya, ю = yu, ё = yo, е = ye. The vowel ы has no English equivalent: say \"i\" with your tongue pulled back. The soft sign ь has no sound of its own — it softens the consonant before it.","Every word has one stressed syllable, and it can fall on any syllable — there is no fixed rule. Learner materials mark it with an accent: молоко́ (milk). Ordinary texts do not, so learn the stress together with each word. The letter ё is always stressed.","As in English, unstressed vowels get weaker: unstressed о sounds like а, and unstressed е or я sound close to и. So молоко́ sounds like \"malakó\", and спаси́бо (thank you) like \"spasíba\"."]},"table":{"head":{"he":["אות","צליל","דוגמה"],"en":["Letter","Sound","Example"]},"rows":[["В в",{"he":"ו","en":"v"},"вот"],["Н н",{"he":"נ","en":"n"},"нос"],["Р р",{"he":"ר מתגלגלת","en":"rolled r"},"рука́"],["С с",{"he":"ס","en":"s"},"сок"],["Х х",{"he":"ח","en":"kh (as in loch)"},"хлеб"],["У у",{"he":"או","en":"oo"},"ум"],["Ы ы",{"he":"\"אי\" עמוקה","en":"a deep \"i\""},"мы"],["Я я",{"he":"יא","en":"ya"},"я"],["о́ / о",{"he":"או / א (לא מוטעמת)","en":"o / a (unstressed)"},"молоко́"]]},"examples":[{"t":"ма́ма","p":{"he":"מאמא","en":"máma"},"m":{"he":"אמא","en":"mum"}},{"t":"па́па","p":{"he":"פאפא","en":"pápa"},"m":{"he":"אבא","en":"dad"}},{"t":"молоко́","p":{"he":"מלקו","en":"molokó"},"m":{"he":"חלב","en":"milk"}},{"t":"вода́","p":{"he":"ודא","en":"vodá"},"m":{"he":"מים","en":"water"}},{"t":"спаси́бо","p":{"he":"ספסיבא","en":"spasíbo"},"m":{"he":"תודה","en":"thank you"}},{"t":"хорошо́","p":{"he":"חרשו","en":"khoroshó"},"m":{"he":"טוב; בסדר","en":"good; fine"}},{"t":"кни́га","p":{"he":"קניגא","en":"kníga"},"m":{"he":"ספר","en":"book"}},{"t":"Москва́","p":{"he":"מסקווא","en":"Moskvá"},"m":{"he":"מוסקבה","en":"Moscow"}}],"quiz":[{"q":{"he":"איזו אות נשמעת כמו ו (V)?","en":"Which letter sounds like v?"},"opts":["В","У","Н","Б"],"a":0,"why":{"he":"В = ו. האות Б היא ב.","en":"В = v. The letter Б is b."}},{"q":{"he":"איזו אות נשמעת כמו ס?","en":"Which letter sounds like s?"},"opts":["З","С","Ш","Р"],"a":1,"why":{"he":"С = ס. Р היא ר, З היא ז, Ш היא ש.","en":"С = s. Р is r, З is z, Ш is sh."}},{"q":{"he":"איזו אות נשמעת כמו ר?","en":"Which letter sounds like r?"},"opts":["Я","П","Г","Р"],"a":3,"why":{"he":"Р = ר. П היא פ.","en":"Р = r. П is p."}},{"q":{"he":"איזו אות נשמעת כמו ח?","en":"Which letter sounds like kh (as in loch)?"},"opts":["К","Ч","Х","Ж"],"a":2,"why":{"he":"Х = ח: хлеб — לחם.","en":"Х = kh: хлеб — bread."}},{"q":{"he":"כמה אותיות יש באלפבית הרוסי?","en":"How many letters are there in the Russian alphabet?"},"opts":["36","26","22","33"],"a":3,"why":{"he":"ברוסית 33 אותיות.","en":"Russian has 33 letters."}},{"q":{"he":"איזו אות תמיד מוטעמת?","en":"Which letter is always stressed?"},"opts":["ё","ю","э","е"],"a":0,"why":{"he":"ё (יו) תמיד מוטעמת.","en":"ё (yo) is always stressed."}},{"q":{"he":"איך נשמעת о הראשונה ב-молоко́ (לא מוטעמת)?","en":"How does the first, unstressed о in молоко́ sound?"},"opts":["у","а","ы","о"],"a":1,"why":{"he":"о שאינה מוטעמת נשמעת כמו а: \"מלקו\".","en":"Unstressed о sounds like а: \"malakó\"."}},{"q":{"he":"איפה ההטעמה הנכונה במילה \"בבקשה\"?","en":"Where is the correct stress in \"please\"?"},"opts":["по́жалуйста","пожалу́йста","пожа́луйста","пожалуйста́"],"a":2,"why":{"he":"пожа́луйста — ההטעמה בהברה השנייה.","en":"пожа́луйста — stress on the second syllable."}}]},{"id":"gender","level":"A1","title":{"he":"מין של שמות עצם","en":"Gender of nouns"},"text":{"he":["בעברית יש שני מינים, ברוסית — שלושה: זכר, נקבה וסתמי (נייטרלי). כמעט תמיד אפשר לזהות את המין לפי סוף המילה.","זכר — מסתיים בעיצור או ב-й: стол (שולחן), дом (בית), музе́й (מוזיאון). נקבה — מסתיימת ב-а או ב-я: ма́ма, кни́га (ספר), неде́ля (שבוע). סתמי — מסתיים ב-о או ב-е: окно́ (חלון), мо́ре (ים).","מילים שמסתיימות ב-ь יכולות להיות זכר או נקבה, ואת זה צריך ללמוד: день (יום) — זכר, ночь (לילה) — נקבה. מילים על גברים הן בזכר גם כשהן מסתיימות ב-а: па́па (אבא).","המין ברוסית לא תמיד זהה לעברית: кни́га (ספר) היא נקבה, ו-мо́ре (ים) הוא סתמי. על חפצים אומרים он, она́ או оно́ לפי המין, ומילת השייכות מתאימה את עצמה: мой дом, моя́ кни́га, моё окно́."],"en":["Russian nouns have grammatical gender — masculine, feminine or neuter — even when they name things. You can usually tell the gender from the last letter.","Masculine nouns end in a consonant or -й: стол (table), дом (house), музе́й (museum). Feminine nouns end in -а or -я: ма́ма, кни́га (book), неде́ля (week). Neuter nouns end in -о or -е: окно́ (window), мо́ре (sea).","Nouns ending in the soft sign -ь can be masculine or feminine, so learn them with their gender: день (day) is masculine, ночь (night) is feminine. Words for men are masculine even with -а: па́па (dad).","There is no single word for \"it\": a table is он (he), a book is она́ (she), a window is оно́ (it). Words like \"my\" change with the gender too: мой дом, моя́ кни́га, моё окно́."]},"table":{"head":{"he":["מין","סיומת","דוגמאות"],"en":["Gender","Ending","Examples"]},"rows":[[{"he":"זכר","en":"masculine"},{"he":"עיצור / -й","en":"consonant / -й"},"стол, музе́й"],[{"he":"נקבה","en":"feminine"},"-а / -я","ма́ма, неде́ля"],[{"he":"סתמי","en":"neuter"},"-о / -е","окно́, мо́ре"],[{"he":"זכר או נקבה","en":"masculine or feminine"},"-ь","день (он), ночь (она́)"]]},"examples":[{"t":"Э́то мой дом.","p":{"he":"אטא מוי דום.","en":"Éto moy dom."},"m":{"he":"זה הבית שלי.","en":"This is my house."}},{"t":"Э́то моя́ кни́га.","p":{"he":"אטא מאיא קניגא.","en":"Éto moyá kníga."},"m":{"he":"זה הספר שלי.","en":"This is my book."}},{"t":"Э́то моё окно́.","p":{"he":"אטא מאיו אקנו.","en":"Éto moyó oknó."},"m":{"he":"זה החלון שלי.","en":"This is my window."}},{"t":"Где стол? — Вот он.","p":{"he":"גדה סטול? — ווט און.","en":"Gde stol? — Vot on."},"m":{"he":"איפה השולחן? — הנה הוא.","en":"Where is the table? — Here it is."}},{"t":"Где ма́ма? — Вот она́.","p":{"he":"גדה מאמא? — ווט אנא.","en":"Gde máma? — Vot oná."},"m":{"he":"איפה אמא? — הנה היא.","en":"Where is mum? — Here she is."}},{"t":"Где метро́? — Вот оно́.","p":{"he":"גדה מיטרו? — ווט אנו.","en":"Gde metró? — Vot onó."},"m":{"he":"איפה המטרו? — הנה הוא.","en":"Where is the metro? — Here it is."}},{"t":"Мой па́па — врач.","p":{"he":"מוי פאפא — וראץ׳.","en":"Moy pápa — vrach."},"m":{"he":"אבא שלי רופא.","en":"My dad is a doctor."}}],"quiz":[{"q":{"he":"השלימו: ___ кни́га","en":"Fill in: ___ кни́га (my book)"},"opts":["мой","моё","моя́","мои́"],"a":2,"why":{"he":"кни́га היא נקבה (‎-а) → моя́.","en":"кни́га is feminine (-а) → моя́."}},{"q":{"he":"השלימו: ___ окно́","en":"Fill in: ___ окно́ (my window)"},"opts":["мой","моё","моя́","мои́"],"a":1,"why":{"he":"окно́ הוא סתמי (‎-о) → моё.","en":"окно́ is neuter (-о) → моё."}},{"q":{"he":"השלימו: ___ стол","en":"Fill in: ___ стол (my table)"},"opts":["мой","моё","моя́","мои́"],"a":0,"why":{"he":"стол מסתיים בעיצור — זכר → мой.","en":"стол ends in a consonant — masculine → мой."}},{"q":{"he":"איזו מילה היא בסתמי?","en":"Which noun is neuter?"},"opts":["ма́ма","стол","ночь","мо́ре"],"a":3,"why":{"he":"мо́ре מסתיים ב-е — סתמי.","en":"мо́ре ends in -е — neuter."}},{"q":{"he":"איזו מילה היא בזכר, למרות הסיומת ‎-а?","en":"Which noun is masculine despite ending in -а?"},"opts":["неде́ля","кни́га","ма́ма","па́па"],"a":3,"why":{"he":"па́па (אבא) הוא גבר, ולכן זכר.","en":"па́па (dad) is a man, so the word is masculine."}},{"q":{"he":"איזו מילה היא בנקבה?","en":"Which noun is feminine?"},"opts":["дом","ночь","день","окно́"],"a":1,"why":{"he":"ночь (לילה) — נקבה. день (יום) — זכר.","en":"ночь (night) is feminine; день (day) is masculine."}},{"q":{"he":"Где музе́й? — Вот ___.","en":"Где музе́й? — Вот ___. (Where is the museum? — Here it is.)"},"opts":["оно́","она́","он","они́"],"a":2,"why":{"he":"музе́й (‎-й) הוא זכר → он.","en":"музе́й (-й) is masculine → он."}},{"q":{"he":"Где ко́мната? — Вот ___.","en":"Где ко́мната? — Вот ___. (Where is the room? — Here it is.)"},"opts":["она́","оно́","они́","он"],"a":0,"why":{"he":"ко́мната (חדר) מסתיימת ב-а — נקבה → она́.","en":"ко́мната (room) ends in -а — feminine → она́."}}]},{"id":"plural","level":"A1","title":{"he":"רבים","en":"Plural"},"text":{"he":["ברבים, מילים בזכר ובנקבה מקבלות בדרך כלל ‎-ы או ‎-и: стол → столы́, ма́ма → ма́мы. מילים בסתמי מקבלות ‎-а או ‎-я: окно́ → о́кна, мо́ре → моря́.","מתי ‎-и? אחרי ь, й ו-я: музе́й → музе́и, неде́ля → неде́ли; וגם אחרי האותיות г, к, х, ж, ш, ч, щ — אחריהן אף פעם לא כותבים ы: кни́га → кни́ги, ключ → ключи́ (מפתחות).","בעברית הסיומת תלויה במין (‎-ים, ‎-ות). ברוסית היא תלויה באות האחרונה, ואין צורה זוגית. שימו לב: ההטעמה זזה לפעמים ברבים: окно́ → о́кна, стол → столы́.","יש מילים חריגות שפשוט לומדים: челове́к → лю́ди (אנשים), ребёнок → де́ти (ילדים), друг → друзья́ (חברים), дом → дома́ (בתים)."],"en":["Masculine and feminine nouns usually take -ы or -и in the plural: стол → столы́, ма́ма → ма́мы. Neuter nouns take -а or -я: окно́ → о́кна, мо́ре → моря́.","When -и? After ь, й and я: музе́й → музе́и, неде́ля → неде́ли; and after г, к, х, ж, ш, ч, щ, which are never followed by ы in writing: кни́га → кни́ги, ключ → ключи́ (keys).","Unlike the English -s, the Russian ending depends on how the word ends. The stress can also move in the plural: окно́ → о́кна, стол → столы́.","Some plurals are irregular and must be learned, like English man → men: челове́к → лю́ди (people), ребёнок → де́ти (children), друг → друзья́ (friends), дом → дома́ (houses)."]},"table":{"head":{"he":["יחיד","רבים"],"en":["Singular","Plural"]},"rows":[["стол","столы́"],["ма́ма","ма́мы"],["кни́га","кни́ги"],["музе́й","музе́и"],["неде́ля","неде́ли"],["окно́","о́кна"],["мо́ре","моря́"],["дом","дома́"],["челове́к","лю́ди"],["ребёнок","де́ти"]]},"examples":[{"t":"Э́то мои́ кни́ги.","p":{"he":"אטא מאי קניגי.","en":"Éto moí knígi."},"m":{"he":"אלה הספרים שלי.","en":"These are my books."}},{"t":"Где мои́ ключи́?","p":{"he":"גדה מאי קליוצ׳י?","en":"Gde moí klyuchí?"},"m":{"he":"איפה המפתחות שלי?","en":"Where are my keys?"}},{"t":"Мои́ де́ти до́ма.","p":{"he":"מאי דטי דומא.","en":"Moí déti dóma."},"m":{"he":"הילדים שלי בבית.","en":"My children are at home."}},{"t":"Там лю́ди.","p":{"he":"טאם ליודי.","en":"Tam lyúdi."},"m":{"he":"יש שם אנשים.","en":"There are people there."}},{"t":"Мои́ друзья́ — студе́нты.","p":{"he":"מאי דרוזיא — סטודנטי.","en":"Moí druzyá — studénty."},"m":{"he":"החברים שלי סטודנטים.","en":"My friends are students."}},{"t":"Здесь больши́е о́кна.","p":{"he":"זדס בלשיי אוקנא.","en":"Zdes bolshíye ókna."},"m":{"he":"יש כאן חלונות גדולים.","en":"There are big windows here."}}],"quiz":[{"q":{"he":"רבים של стол:","en":"Plural of стол:"},"opts":["столо́","столи́","столе́и","столы́"],"a":3,"why":{"he":"стол + ‎-ы → столы́ (ההטעמה עוברת לסוף).","en":"стол + -ы → столы́ (the stress moves to the end)."}},{"q":{"he":"רבים של кни́га:","en":"Plural of кни́га:"},"opts":["кни́ги","кни́гы","кни́ге","кни́гаи"],"a":0,"why":{"he":"אחרי г כותבים и, לא ы: кни́ги.","en":"After г we write и, never ы: кни́ги."}},{"q":{"he":"רבים של окно́:","en":"Plural of окно́:"},"opts":["о́кна","окни́","окны́","окно́ы"],"a":0,"why":{"he":"סתמי ‎-о → ‎-а, וההטעמה זזה: о́кна.","en":"Neuter -о → -а, and the stress moves: о́кна."}},{"q":{"he":"רבים של челове́к (אדם):","en":"Plural of челове́к (person):"},"opts":["челове́кы","людя́","лю́ди","челове́ки"],"a":2,"why":{"he":"צורה חריגה: челове́к → лю́ди.","en":"Irregular: челове́к → лю́ди."}},{"q":{"he":"רבים של ребёнок (ילד):","en":"Plural of ребёнок (child):"},"opts":["дети́","де́ти","ребёнокы","ребёнки"],"a":1,"why":{"he":"צורה חריגה: ребёнок → де́ти.","en":"Irregular: ребёнок → де́ти."}},{"q":{"he":"רבים של ключ (מפתח):","en":"Plural of ключ (key):"},"opts":["клю́чы","ключо́","ключы́","ключи́"],"a":3,"why":{"he":"אחרי ч כותבים и: ключи́.","en":"After ч we write и: ключи́."}},{"q":{"he":"רבים של мо́ре (ים):","en":"Plural of мо́ре (sea):"},"opts":["мо́ры","моря́","мо́ри","морё"],"a":1,"why":{"he":"סתמי ‎-е → ‎-я: моря́.","en":"Neuter -е → -я: моря́."}},{"q":{"he":"Мои́ ___ — студе́нты. (חברים)","en":"Мои́ ___ — студе́нты. (friends)"},"opts":["дру́ги","друзи́","друзья́","друг"],"a":2,"why":{"he":"צורה חריגה: друг → друзья́.","en":"Irregular: друг → друзья́."}}]},{"id":"pronouns_be","level":"A1","title":{"he":"כינויי גוף ו\"להיות\"","en":"Personal pronouns and \"to be\""},"text":{"he":["כינויי הגוף: я (אני), ты (אתה/את), он (הוא), она́ (היא), оно́ (סתמי, לחפצים), мы (אנחנו), вы (אתם/אתן), они́ (הם/הן). ברוסית \"אתה\" ו\"את\" הם אותה מילה: ты.","כמו בעברית, בהווה אין פועל \"להיות\": Я студе́нт — אני סטודנט. בכתב שמים לפעמים קו מפריד בין שני שמות עצם: Мой брат — врач (אחי רופא).","גם יידוע אין: אין \"ה\" ואין מילה ל\"אחד/איזה\". дом זה גם \"בית\" וגם \"הבית\". Э́то פירושו \"זה\" או \"זהו\": Э́то мой брат — זה אחי.","בשונה מעברית, יש פנייה מנומסת: вы. אומרים ты לחברים, למשפחה ולילדים, ו-вы לאדם זר, למבוגר, לרופא או למורה — וגם לכמה אנשים יחד.","שלילה: מוסיפים не לפני המילה: Я не врач — אני לא רופא."],"en":["The pronouns are я (I), ты (you, one friend), он (he), она́ (she), оно́ (it, neuter), мы (we), вы (you, plural or polite), они́ (they). Remember: a table is он and a book is она́.","Russian has no \"am / is / are\" in the present tense. Just put the words side by side: Я студе́нт — I am a student. In writing a dash often stands between two nouns: Мой брат — врач (My brother is a doctor).","There are no articles either — no \"a\" and no \"the\". дом means \"a house\" or \"the house\". Э́то means \"this is / it is\": Э́то мой брат — This is my brother.","Use ты with friends, family and children, and вы with strangers, older people, doctors or teachers — and with any group of people.","To make a negative, put не in front: Я не врач — I am not a doctor."]},"table":{"head":{"he":["רוסית","עברית"],"en":["Russian","English"]},"rows":[["я",{"he":"אני","en":"I"}],["ты",{"he":"אתה / את","en":"you (one person, informal)"}],["он",{"he":"הוא","en":"he; it (masculine noun)"}],["она́",{"he":"היא","en":"she; it (feminine noun)"}],["оно́",{"he":"הוא/היא (שם עצם סתמי)","en":"it (neuter noun)"}],["мы",{"he":"אנחנו","en":"we"}],["вы",{"he":"אתם / אתן; אתה/את בנימוס","en":"you (plural or polite)"}],["они́",{"he":"הם / הן","en":"they"}]]},"examples":[{"t":"Я студе́нт.","p":{"he":"יא סטודנט.","en":"Ya studént."},"m":{"he":"אני סטודנט.","en":"I am a student."}},{"t":"Ты врач?","p":{"he":"טי וראץ׳?","en":"Ty vrach?"},"m":{"he":"אתה רופא?","en":"Are you a doctor?"}},{"t":"Она́ до́ма.","p":{"he":"אנא דומא.","en":"Oná dóma."},"m":{"he":"היא בבית.","en":"She is at home."}},{"t":"Мы из Изра́иля.","p":{"he":"מי איז איזראיליא.","en":"My iz Izráilya."},"m":{"he":"אנחנו מישראל.","en":"We are from Israel."}},{"t":"Вы учи́тель?","p":{"he":"וי אוצ׳יטיל?","en":"Vy uchítel?"},"m":{"he":"אתה מורה? (בנימוס)","en":"Are you a teacher? (polite)"}},{"t":"Они́ здесь.","p":{"he":"אני זדס.","en":"Oní zdes."},"m":{"he":"הם כאן.","en":"They are here."}},{"t":"Э́то мой брат.","p":{"he":"אטא מוי בראט.","en":"Éto moy brat."},"m":{"he":"זה אחי.","en":"This is my brother."}},{"t":"Я не врач.","p":{"he":"יא ני וראץ׳.","en":"Ya ne vrach."},"m":{"he":"אני לא רופא.","en":"I am not a doctor."}}],"quiz":[{"q":{"he":"איך אומרים \"אני סטודנט\"?","en":"How do you say \"I am a student\"?"},"opts":["Я студе́нт.","Мне студе́нт.","Я есть студе́нт.","Я быть студе́нт."],"a":0,"why":{"he":"בהווה אין \"להיות\": Я студе́нт.","en":"No \"to be\" in the present: Я студе́нт."}},{"q":{"he":"פונים לאיש מבוגר שאינכם מכירים. איזו מילה?","en":"You speak to an older stranger. Which word?"},"opts":["ты","вы","он","мы"],"a":1,"why":{"he":"לזרים ולמבוגרים פונים ב-вы.","en":"Strangers and older people get вы."}},{"q":{"he":"איזה כינוי מחליף את \"А́нна и Ми́ша\"?","en":"Which pronoun replaces \"А́нна и Ми́ша\"?"},"opts":["мы","он","они́","она́"],"a":2,"why":{"he":"שני אנשים → они́ (הם).","en":"Two people → они́ (they)."}},{"q":{"he":"איך אומרים \"אנחנו\"?","en":"How do you say \"we\"?"},"opts":["вы","они́","ты","мы"],"a":3,"why":{"he":"мы = אנחנו; вы = אתם.","en":"мы = we; вы = you (plural)."}},{"q":{"he":"איזה כינוי מתאים ל-окно́ (חלון)?","en":"Which pronoun stands for окно́ (window)?"},"opts":["она́","оно́","он","они́"],"a":1,"why":{"he":"окно́ הוא סתמי → оно́.","en":"окно́ is neuter → оно́."}},{"q":{"he":"איך אומרים \"אני לא רופא\"?","en":"How do you say \"I am not a doctor\"?"},"opts":["Я нет врач.","Нет я врач.","Я не врач.","Я врач не есть."],"a":2,"why":{"he":"שלילה — не לפני המילה.","en":"Negation — не before the word."}},{"q":{"he":"איך אומרים \"זה אחי\"?","en":"How do you say \"This is my brother\"?"},"opts":["Э́то мой брат.","Э́то моя́ брат.","Э́то есть мой брат.","Э́то моё брат."],"a":0,"why":{"he":"Э́то + שם עצם, בלי \"להיות\". брат זכר → мой.","en":"Э́то + noun, no \"to be\". брат is masculine → мой."}},{"q":{"he":"איך אומרים \"היא בבית\"?","en":"How do you say \"She is at home\"?"},"opts":["Она́ быть до́ма.","Она́ есть до́ма.","Она́ — есть до́ма.","Она́ до́ма."],"a":3,"why":{"he":"Она́ до́ма — בלי פועל.","en":"Она́ до́ма — no verb needed."}}]},{"id":"u_menya_est","level":"A1","title":{"he":"\"יש לי\": у меня́ есть","en":"\"I have\": у меня́ есть"},"text":{"he":["ברוסית אומרים \"יש לי\" כמעט כמו בעברית: У меня́ есть брат — יש לי אח. מילה במילה: \"אצלי יש אח\". הפועל име́ть (להחזיק, שיהיה ל-) כמעט לא משמש בדיבור.","אחרי у כינוי הגוף משנה צורה: у меня́, у тебя́, у него́, у неё, у нас, у вас, у них. שימו לב ל-н שנוספת בצורות של он, она́, они́: у него́, у неё, у них. במילה него́ ה-г נשמעת כמו в: \"ניוו\".","בשאלה משנים רק את האינטונציה: У тебя́ есть маши́на? — יש לך מכונית? תשובה קצרה: Да, есть (כן, יש) או Нет (לא).","\"אין לי\" — у меня́ нет, ואחרי нет המילה מקבלת סיומת אחרת (יחסת הקניין, שיעור 11): У меня́ нет вре́мени — אין לי זמן."],"en":["Russian usually says \"I have\" as \"at me there is\": У меня́ есть брат — I have a brother (literally \"at me is a brother\"). The verb име́ть (to have) is rarely used in everyday speech.","After у the pronoun changes form: у меня́, у тебя́, у него́, у неё, у нас, у вас, у них. Note the extra н in the forms for he, she and they: у него́, у неё, у них. In него́ the г is pronounced v: \"nevó\".","To ask, just raise your voice — the words stay the same: У тебя́ есть маши́на? — Do you have a car? Short answers: Да, есть (Yes, I do) or Нет (No).","\"I don't have\" is у меня́ нет, and the noun after нет takes a different ending (the genitive case, lesson 11): У меня́ нет вре́мени — I have no time."]},"table":{"head":{"he":["כינוי","יש ל…"],"en":["Pronoun","… have"]},"rows":[["я","у меня́ есть"],["ты","у тебя́ есть"],["он / оно́","у него́ есть"],["она́","у неё есть"],["мы","у нас есть"],["вы","у вас есть"],["они́","у них есть"]]},"examples":[{"t":"У меня́ есть брат.","p":{"he":"או מיניא יסט בראט.","en":"U menyá yest brat."},"m":{"he":"יש לי אח.","en":"I have a brother."}},{"t":"У тебя́ есть маши́на?","p":{"he":"או טיביא יסט משינא?","en":"U tebyá yest mashína?"},"m":{"he":"יש לך מכונית?","en":"Do you have a car?"}},{"t":"У неё есть соба́ка.","p":{"he":"או ניו יסט סבאקא.","en":"U neyó yest sobáka."},"m":{"he":"יש לה כלב.","en":"She has a dog."}},{"t":"У нас есть вре́мя.","p":{"he":"או נאס יסט ורמיא.","en":"U nas yest vrémya."},"m":{"he":"יש לנו זמן.","en":"We have time."}},{"t":"У вас есть вопро́сы?","p":{"he":"או ואס יסט ופרוסי?","en":"U vas yest voprósy?"},"m":{"he":"יש לכם שאלות?","en":"Do you have any questions?"}},{"t":"У них есть дом.","p":{"he":"או ניח יסט דום.","en":"U nikh yest dom."},"m":{"he":"יש להם בית.","en":"They have a house."}},{"t":"У меня́ нет вре́мени.","p":{"he":"או מיניא נט ורמיני.","en":"U menyá net vrémeni."},"m":{"he":"אין לי זמן.","en":"I have no time."}},{"t":"У тебя́ есть сестра́? — Да, есть.","p":{"he":"או טיביא יסט סיסטרא? — דא, יסט.","en":"U tebyá yest sestrá? — Da, yest."},"m":{"he":"יש לך אחות? — כן, יש.","en":"Do you have a sister? — Yes, I do."}}],"quiz":[{"q":{"he":"איך אומרים \"יש לי מכונית\"?","en":"How do you say \"I have a car\"?"},"opts":["Меня́ есть маши́на.","Я есть маши́на.","У меня́ есть маши́на.","У я есть маши́на."],"a":2,"why":{"he":"כמו \"יש לי\": у меня́ есть.","en":"Literally \"at me is\": у меня́ есть."}},{"q":{"he":"у ___ есть соба́ка (לה)","en":"у ___ есть соба́ка (she has)"},"opts":["она́","её","ей","неё"],"a":3,"why":{"he":"אחרי у: у неё (עם н).","en":"After у: у неё (with н)."}},{"q":{"he":"у ___ есть дом (להם)","en":"у ___ есть дом (they have)"},"opts":["они́","их","им","них"],"a":3,"why":{"he":"у них — עם н.","en":"у них — with н."}},{"q":{"he":"у ___ есть вре́мя (לנו)","en":"у ___ есть вре́мя (we have)"},"opts":["нам","нас","на́ми","мы"],"a":1,"why":{"he":"мы → у нас.","en":"мы → у нас."}},{"q":{"he":"איך שואלים בנימוס \"יש לך שאלות?\"","en":"How do you politely ask \"Do you have questions?\""},"opts":["У вас есть вопро́сы?","Вас есть вопро́сы?","У вы есть вопро́сы?","У вам есть вопро́сы?"],"a":0,"why":{"he":"вы → у вас.","en":"вы → у вас."}},{"q":{"he":"איך אומרים \"אין לי זמן\"?","en":"How do you say \"I have no time\"?"},"opts":["Я нет вре́мени.","У меня́ нет вре́мени.","У меня́ не вре́мя.","У меня́ не есть вре́мя."],"a":1,"why":{"he":"\"אין לי\" — у меня́ нет + יחסת הקניין.","en":"\"I don't have\" — у меня́ нет + genitive."}},{"q":{"he":"У тебя́ есть брат? — Да, ___.","en":"У тебя́ есть брат? — Да, ___. (Yes, I do.)"},"opts":["есть","име́ю","у","ест"],"a":0,"why":{"he":"תשובה קצרה: Да, есть.","en":"Short answer: Да, есть."}},{"q":{"he":"у ___ есть маши́на (לו)","en":"у ___ есть маши́на (he has)"},"opts":["ему́","он","него́","его́"],"a":2,"why":{"he":"אחרי у: у него́ (נשמע \"או ניוו\").","en":"After у: у него́ (sounds \"u nevó\")."}}]},{"id":"present","level":"A1","title":{"he":"הווה: שתי הנטיות","en":"Present tense: two conjugations"},"text":{"he":["בעברית פועל בהווה משתנה לפי מין ומספר (כותב, כותבת, כותבים). ברוסית הוא משתנה לפי גוף: לכל אחד מ-я, ты, он/она́, мы, вы, они́ סיומת משלו, ואין הבדל בין גבר לאישה.","יש שתי קבוצות (נטיות). נטייה ראשונה — בעיקר פעלים על ‎-ать: де́лать (לעשות), чита́ть (לקרוא), рабо́тать (לעבוד), знать (לדעת). הסיומות: ‎-ю (‎-у), ‎-ешь, ‎-ет, ‎-ем, ‎-ете, ‎-ют (‎-ут).","נטייה שנייה — בעיקר פעלים על ‎-ить: говори́ть (לדבר), люби́ть (לאהוב). הסיומות: ‎-ю (‎-у), ‎-ишь, ‎-ит, ‎-им, ‎-ите, ‎-ят (‎-ат). בחלק מהפעלים נוספת ל בגוף я: люблю́ (אני אוהב).","יש גם פעלים לא סדירים שלומדים בעל פה, למשל жить (לגור, לחיות): живу́, живёшь, живёт. כינוי הגוף נאמר כמעט תמיד, אף שהסיומת כבר מראה מי עושה."],"en":["Russian verbs change for every person: я, ты, он/она́, мы, вы, они́ each have their own ending (English only adds -s for he/she). In the present tense the form does not depend on gender.","There are two main patterns. 1st conjugation — mostly verbs in -ать: де́лать (do), чита́ть (read), рабо́тать (work), знать (know). Endings: -ю (-у), -ешь, -ет, -ем, -ете, -ют (-ут).","2nd conjugation — mostly verbs in -ить: говори́ть (speak), люби́ть (love, like). Endings: -ю (-у), -ишь, -ит, -им, -ите, -ят (-ат). Some verbs add an л in the я form: люблю́ (I love).","Some verbs are irregular and must be learned, for example жить (live): живу́, живёшь, живёт. Russian has no separate \"-ing\" form: я чита́ю means both \"I read\" and \"I am reading\"."]},"table":{"head":{"he":["כינוי","де́лать (נטייה 1)","говори́ть (נטייה 2)"],"en":["Pronoun","де́лать (1st)","говори́ть (2nd)"]},"rows":[["я","де́лаю","говорю́"],["ты","де́лаешь","говори́шь"],["он / она́","де́лает","говори́т"],["мы","де́лаем","говори́м"],["вы","де́лаете","говори́те"],["они́","де́лают","говоря́т"]]},"examples":[{"t":"Я рабо́таю в ба́нке.","p":{"he":"יא רבוטאיו ובאנקי.","en":"Ya rabótayu v bánke."},"m":{"he":"אני עובד בבנק.","en":"I work in a bank."}},{"t":"Что ты де́лаешь?","p":{"he":"שטו טי דלאיש?","en":"Shto ty délayesh?"},"m":{"he":"מה אתה עושה?","en":"What are you doing?"}},{"t":"Я зна́ю.","p":{"he":"יא זנאיו.","en":"Ya znáyu."},"m":{"he":"אני יודע.","en":"I know."}},{"t":"Она́ чита́ет кни́гу.","p":{"he":"אנא צ׳יטאיט קניגו.","en":"Oná chitáyet knígu."},"m":{"he":"היא קוראת ספר.","en":"She is reading a book."}},{"t":"Мы говори́м по-ру́сски.","p":{"he":"מי גוורים פרוסקי.","en":"My govorím po-rússki."},"m":{"he":"אנחנו מדברים רוסית.","en":"We speak Russian."}},{"t":"Вы говори́те по-англи́йски?","p":{"he":"וי גווריטי פאאנגליסקי?","en":"Vy govoríte po-anglíyski?"},"m":{"he":"אתה מדבר אנגלית? (בנימוס)","en":"Do you speak English?"}},{"t":"Они́ живу́т в Изра́иле.","p":{"he":"אני ז׳יווט ויזראילי.","en":"Oní zhivút v Izráile."},"m":{"he":"הם גרים בישראל.","en":"They live in Israel."}},{"t":"Я люблю́ ко́фе.","p":{"he":"יא ליובליו קופי.","en":"Ya lyublyú kófe."},"m":{"he":"אני אוהב קפה.","en":"I love coffee."}}],"quiz":[{"q":{"he":"Я ___ (знать)","en":"Я ___ (знать — to know)"},"opts":["зна́ю","знать","зна́ешь","зна́ем"],"a":0,"why":{"he":"я → ‎-ю: зна́ю.","en":"я → -ю: зна́ю."}},{"q":{"he":"Ты ___ по-ру́сски? (говори́ть)","en":"Ты ___ по-ру́сски? (говори́ть — to speak)"},"opts":["говорю́","говори́шь","говори́ть","говоря́т"],"a":1,"why":{"he":"נטייה 2, ты → ‎-ишь: говори́шь.","en":"2nd conjugation, ты → -ишь: говори́шь."}},{"q":{"he":"Они́ ___ газе́ту. (чита́ть)","en":"Они́ ___ газе́ту. (чита́ть — to read)"},"opts":["чита́ет","чита́ем","чита́ют","чита́ете"],"a":2,"why":{"he":"они́ → ‎-ют: чита́ют.","en":"они́ → -ют: чита́ют."}},{"q":{"he":"Мы ___ по-ру́сски. (говори́ть)","en":"Мы ___ по-ру́сски. (говори́ть)"},"opts":["говори́т","говори́м","говори́те","говоря́т"],"a":1,"why":{"he":"мы → ‎-им: говори́м.","en":"мы → -им: говори́м."}},{"q":{"he":"Я ___ ко́фе. (люби́ть)","en":"Я ___ ко́фе. (люби́ть — to love)"},"opts":["люблю́","лю́бишь","лю́бит","любю́"],"a":0,"why":{"he":"בגוף я נוספת ל: люблю́.","en":"The я form adds л: люблю́."}},{"q":{"he":"Что вы ___? (де́лать) — מה אתם עושים?","en":"Что вы ___? (де́лать) — What are you doing?"},"opts":["де́лают","де́лаешь","де́лает","де́лаете"],"a":3,"why":{"he":"вы → ‎-ете: де́лаете.","en":"вы → -ете: де́лаете."}},{"q":{"he":"Он ___ в Изра́иле. (жить)","en":"Он ___ в Изра́иле. (жить — to live)"},"opts":["жит","живи́т","живёт","жи́вет"],"a":2,"why":{"he":"פועל לא סדיר: живу́, живёшь, живёт.","en":"Irregular: живу́, живёшь, живёт."}},{"q":{"he":"איזו סיומת של ты שייכת לנטייה השנייה?","en":"Which ты ending belongs to the 2nd conjugation?"},"opts":["-ют","-ет","-ешь","-ишь"],"a":3,"why":{"he":"נטייה 2: ‎-ишь (говори́шь). נטייה 1: ‎-ешь.","en":"2nd: -ишь (говори́шь). 1st: -ешь."}}]},{"id":"past","level":"A2","title":{"he":"עבר: סיומות לפי מין","en":"Past tense: gender endings"},"text":{"he":["את העבר בונים בקלות: מורידים ‎-ть מהמקור ומוסיפים ‎-л: рабо́тать → рабо́тал. אין סיומות לפי גוף — я, ты ו-он אומרים рабо́тал.","אבל הפועל משתנה לפי מין ומספר — הפוך מעברית, שבה \"עבדתי\" זהה לגבר ולאישה: גבר אומר я рабо́тал, אישה אומרת я рабо́тала. זכר ‎-л, נקבה ‎-ла, סתמי ‎-ло, רבים ‎-ли (לכל המינים): мы рабо́тали.","בעבר יש פועל \"להיות\": был (זכר), была́ (נקבה), бы́ло (סתמי), бы́ли (רבים). Я был до́ма — הייתי בבית (גבר); Я была́ до́ма — הייתי בבית (אישה).","כשאין נושא (\"היה קר\"), משתמשים בסתמי: Вчера́ бы́ло хо́лодно — אתמול היה קר. יש פעלים חריגים: идти́ (ללכת) → шёл, шла, шло, шли."],"en":["The past tense is easy to build: take the infinitive, drop -ть and add -л: рабо́тать → рабо́тал. There are no person endings — я, ты and он all say рабо́тал.","Instead, the past changes by gender and number. A man says я рабо́тал, a woman says я рабо́тала. Endings: -л (masculine), -ла (feminine), -ло (neuter), -ли (plural, any gender): мы рабо́тали.","In the past, \"to be\" does appear: был (masculine), была́ (feminine), бы́ло (neuter), бы́ли (plural). Я был до́ма — I was at home (a man speaking); Я была́ до́ма — the same, said by a woman.","With no subject (\"it was cold\") use the neuter: Вчера́ бы́ло хо́лодно — It was cold yesterday. Some verbs are irregular: идти́ (to go) → шёл, шла, шло, шли."]},"table":{"head":{"he":["מקור","הוא","היא","סתמי","הם/הן"],"en":["Infinitive","he","she","it","they"]},"rows":[["рабо́тать","рабо́тал","рабо́тала","рабо́тало","рабо́тали"],["говори́ть","говори́л","говори́ла","говори́ло","говори́ли"],["быть","был","была́","бы́ло","бы́ли"],["идти́","шёл","шла","шло","шли"]]},"examples":[{"t":"Вчера́ я рабо́тал.","p":{"he":"פצ׳ירא יא רבוטל.","en":"Vcherá ya rabótal."},"m":{"he":"אתמול עבדתי. (גבר)","en":"I worked yesterday. (a man)"}},{"t":"Вчера́ я рабо́тала.","p":{"he":"פצ׳ירא יא רבוטלא.","en":"Vcherá ya rabótala."},"m":{"he":"אתמול עבדתי. (אישה)","en":"I worked yesterday. (a woman)"}},{"t":"Где ты был?","p":{"he":"גדה טי ביל?","en":"Gde ty byl?"},"m":{"he":"איפה היית? (לגבר)","en":"Where were you? (to a man)"}},{"t":"Она́ была́ до́ма.","p":{"he":"אנא בילא דומא.","en":"Oná bylá dóma."},"m":{"he":"היא הייתה בבית.","en":"She was at home."}},{"t":"Мы жи́ли в Москве́.","p":{"he":"מי ז׳ילי ומסקווה.","en":"My zhíli v Moskvé."},"m":{"he":"גרנו במוסקבה.","en":"We lived in Moscow."}},{"t":"Они́ чита́ли кни́гу.","p":{"he":"אני צ׳יטאלי קניגו.","en":"Oní chitáli knígu."},"m":{"he":"הם קראו ספר.","en":"They were reading a book."}},{"t":"Что ты де́лала вчера́?","p":{"he":"שטו טי דללא פצ׳ירא?","en":"Shto ty délala vcherá?"},"m":{"he":"מה עשית אתמול? (לאישה)","en":"What did you do yesterday? (to a woman)"}},{"t":"Фильм был интере́сный.","p":{"he":"פילם ביל אינטירסני.","en":"Film byl interésnyy."},"m":{"he":"הסרט היה מעניין.","en":"The film was interesting."}}],"quiz":[{"q":{"he":"אנה אומרת: \"Вчера́ я ___ до́ма.\"","en":"Anna says: \"Вчера́ я ___ до́ма.\""},"opts":["бы́ло","был","была́","бы́ли"],"a":2,"why":{"he":"אישה → была́.","en":"A woman → была́."}},{"q":{"he":"דוד אומר: \"Я ___ кни́гу.\" (чита́ть)","en":"David says: \"Я ___ кни́гу.\" (чита́ть)"},"opts":["чита́ло","чита́ли","чита́ла","чита́л"],"a":3,"why":{"he":"גבר → ‎-л: чита́л.","en":"A man → -л: чита́л."}},{"q":{"he":"Мы ___ в Москве́. (жить, עבר)","en":"Мы ___ в Москве́. (жить, past)"},"opts":["жи́ли","жила́","жил","живём"],"a":0,"why":{"he":"רבים → ‎-ли: жи́ли. живём הוא הווה.","en":"Plural → -ли: жи́ли. живём is present."}},{"q":{"he":"Они́ ___ по-ру́сски. (говори́ть, עבר)","en":"Они́ ___ по-ру́сски. (говори́ть, past)"},"opts":["говори́ла","говори́л","говори́ли","говори́ло"],"a":2,"why":{"he":"они́ → ‎-ли.","en":"они́ → -ли."}},{"q":{"he":"\"Ма́ша, что ты ___ вчера́?\" (де́лать)","en":"\"Ма́ша, что ты ___ вчера́?\" (де́лать)"},"opts":["де́лаешь","де́лал","де́лали","де́лала"],"a":3,"why":{"he":"מדברים אל אישה → ‎-ла.","en":"Talking to a woman → -ла."}},{"q":{"he":"עבר של идти́ (הוא):","en":"Past of идти́ (he):"},"opts":["шла","шёл","идл","идёл"],"a":1,"why":{"he":"צורה חריגה: он шёл, она́ шла.","en":"Irregular: он шёл, она́ шла."}},{"q":{"he":"Ра́ньше здесь ___ магази́н. (פעם הייתה כאן חנות)","en":"Ра́ньше здесь ___ магази́н. (There used to be a shop here.)"},"opts":["был","бы́ли","была́","бы́ло"],"a":0,"why":{"he":"магази́н (חנות) הוא זכר → был.","en":"магази́н is masculine → был."}},{"q":{"he":"Вчера́ ___ хо́лодно. (אתמול היה קר)","en":"Вчера́ ___ хо́лодно. (It was cold yesterday.)"},"opts":["бы́ли","бы́ло","был","была́"],"a":1,"why":{"he":"אין נושא → סתמי: бы́ло.","en":"No subject → neuter: бы́ло."}}]},{"id":"motion","level":"A2","title":{"he":"פעלי תנועה: идти́ ו-е́хать","en":"Verbs of motion: идти́ and е́хать"},"text":{"he":["ברוסית, כמו בעברית, מבדילים בין ללכת ברגל לבין לנסוע: идти́ = ללכת (ברגל), е́хать = לנסוע (באוטובוס, במכונית, ברכבת). Я иду́ — אני הולך; Я е́ду — אני נוסע.","שני הפעלים לא סדירים, ולכן כדאי ללמוד אותם בעל פה (ראו בטבלה). את כלי התחבורה אומרים עם на: на авто́бусе (באוטובוס), на маши́не (במכונית), на по́езде (ברכבת).","שאלת הכיוון היא куда́? (לאן?), והתשובה באה עם в או на וסיומת של יחסת המושא (שיעור 10): в шко́лу (לבית הספר), на рабо́ту (לעבודה). \"הביתה\" — домо́й.","идти́ ו-е́хать מתארים תנועה אחת בכיוון אחד, בדרך כלל עכשיו. להרגל או לנסיעות הלוך ושוב יש זוג אחר: ходи́ть ו-е́здить. Я ча́сто хожу́ в кино́ — אני הולך הרבה לקולנוע."],"en":["English \"go\" is two different verbs in Russian: идти́ — to go on foot, е́хать — to go by vehicle (bus, car, train). Я иду́ — I am going (walking); Я е́ду — I am going (riding).","Both verbs are irregular, so learn them from the table. Transport is said with на: на авто́бусе (by bus), на маши́не (by car), на по́езде (by train).","\"Where to?\" is куда́?, and the answer uses в or на with the accusative ending (lesson 10): в шко́лу (to school), на рабо́ту (to work). \"Home\", as a direction, is домо́й.","идти́ and е́хать describe one trip in one direction, usually right now. For habits and round trips there is another pair: ходи́ть and е́здить. Я ча́сто хожу́ в кино́ — I often go to the cinema."]},"table":{"head":{"he":["כינוי","идти́ (ברגל)","е́хать (בכלי רכב)"],"en":["Pronoun","идти́ (on foot)","е́хать (by vehicle)"]},"rows":[["я","иду́","е́ду"],["ты","идёшь","е́дешь"],["он / она́","идёт","е́дет"],["мы","идём","е́дем"],["вы","идёте","е́дете"],["они́","иду́т","е́дут"]]},"examples":[{"t":"Я иду́ домо́й.","p":{"he":"יא אידו דמוי.","en":"Ya idú domóy."},"m":{"he":"אני הולך הביתה.","en":"I am going home."}},{"t":"Куда́ ты идёшь?","p":{"he":"קודא טי אידיוש?","en":"Kudá ty idyósh?"},"m":{"he":"לאן אתה הולך?","en":"Where are you going?"}},{"t":"Мы е́дем в Тель-Ави́в.","p":{"he":"מי ידים פטל-אוויף.","en":"My yédem v Tel-Avív."},"m":{"he":"אנחנו נוסעים לתל אביב.","en":"We are going to Tel Aviv."}},{"t":"Она́ е́дет на рабо́ту на авто́бусе.","p":{"he":"אנא ידיט נא רבוטו נא אפטובוסי.","en":"Oná yédet na rabótu na avtóbuse."},"m":{"he":"היא נוסעת לעבודה באוטובוס.","en":"She is going to work by bus."}},{"t":"Они́ иду́т в парк.","p":{"he":"אני אידוט פפארק.","en":"Oní idút v park."},"m":{"he":"הם הולכים לפארק.","en":"They are walking to the park."}},{"t":"Ты е́дешь на маши́не?","p":{"he":"טי ידיש נא משיני?","en":"Ty yédesh na mashíne?"},"m":{"he":"אתה נוסע במכונית?","en":"Are you going by car?"}},{"t":"Куда́ вы е́дете?","p":{"he":"קודא וי ידיטי?","en":"Kudá vy yédete?"},"m":{"he":"לאן אתם נוסעים?","en":"Where are you going? (by transport)"}},{"t":"Я ча́сто хожу́ в кино́.","p":{"he":"יא צ׳אסטא חז׳ו פקינו.","en":"Ya chásto khozhú v kinó."},"m":{"he":"אני הולך הרבה לקולנוע.","en":"I often go to the cinema."}}],"quiz":[{"q":{"he":"Я ___ в магази́н пешко́м. (ברגל)","en":"Я ___ в магази́н пешко́м. (on foot)"},"opts":["идёт","иду́","е́дет","е́ду"],"a":1,"why":{"he":"ברגל, я → иду́.","en":"On foot, я → иду́."}},{"q":{"he":"Мы ___ в Хайфу́ на по́езде.","en":"Мы ___ в Хайфу́ на по́езде. (by train)"},"opts":["е́дут","идём","иду́т","е́дем"],"a":3,"why":{"he":"ברכבת → е́хать; мы → е́дем.","en":"By train → е́хать; мы → е́дем."}},{"q":{"he":"Куда́ ты ___? (ברגל)","en":"Куда́ ты ___? (on foot)"},"opts":["идёт","иду́","е́ду","идёшь"],"a":3,"why":{"he":"ты → идёшь.","en":"ты → идёшь."}},{"q":{"he":"Они́ ___ на авто́бусе.","en":"Они́ ___ на авто́бусе."},"opts":["иду́т","идёт","е́дут","е́дет"],"a":2,"why":{"he":"באוטובוס → е́хать; они́ → е́дут.","en":"By bus → е́хать; они́ → е́дут."}},{"q":{"he":"איזה פועל מתאים לנסיעה במכונית?","en":"Which verb fits a trip by car?"},"opts":["ходи́ть","е́хать","идти́","жить"],"a":1,"why":{"he":"בכלי רכב → е́хать.","en":"By vehicle → е́хать."}},{"q":{"he":"Я ча́сто ___ в кино́. (ברגל, הרגל)","en":"Я ча́сто ___ в кино́. (on foot, as a habit)"},"opts":["хожу́","хо́дит","е́ду","иду́"],"a":0,"why":{"he":"הרגל → ходи́ть: я хожу́.","en":"A habit → ходи́ть: я хожу́."}},{"q":{"he":"Я иду́ ___. (הביתה)","en":"Я иду́ ___. (home)"},"opts":["до́ма","до́му","домо́й","дом"],"a":2,"why":{"he":"כיוון \"הביתה\" — домо́й. до́ма = בבית.","en":"Direction home — домо́й. до́ма means \"at home\"."}},{"q":{"he":"Он ___ на рабо́ту на маши́не.","en":"Он ___ на рабо́ту на маши́не."},"opts":["е́дет","е́ду","идёт","иду́т"],"a":0,"why":{"he":"במכונית → е́хать; он → е́дет.","en":"By car → е́хать; он → е́дет."}}]},{"id":"prepositional","level":"A2","title":{"he":"יחסות; יחסת המקום (в/на + где?)","en":"Cases; the prepositional case (в/на + где?)"},"text":{"he":["ברוסית שם העצם משנה את סופו לפי תפקידו במשפט. לצורות האלה קוראים יחסות (падежи́), ויש שש: צורת היסוד (הנושא), יחסת הקניין (\"של\"), יחסת הנמען (\"ל-\"), יחסת המושא (\"את\"), יחסת הכלי (\"עם\", \"באמצעות\") ויחסת המקום. בעברית שם העצם לא משתנה — רק מילת היחס (ב-, ל-, את). ברוסית יש גם מילת יחס וגם סיומת.","יחסת המקום (предло́жный паде́ж) עונה על השאלה где? (איפה?) ובאה אחרי в (ב-, בתוך) או на (על). ברוב המילים הסיומת היא ‎-е: дом → в до́ме, Москва́ → в Москве́, шко́ла → в шко́ле.","מילים על ‎-ия מקבלות ‎-ии: Росси́я → в Росси́и. מילים בנקבה על ‎-ь מקבלות ‎-и: тетра́дь → в тетра́ди (במחברת).","в פירושו \"בתוך\", ו-на — \"על\". אבל עם חלק מהמילים אומרים на גם במובן \"ב-\": на рабо́те (בעבודה), на у́лице (ברחוב, בחוץ), на по́чте (בדואר). את המילים האלה לומדים בעל פה.","אותה יחסה באה גם אחרי о (על, בנושא): Мы говори́м о ма́ме — אנחנו מדברים על אמא."],"en":["Russian nouns change their endings to show their role in the sentence. These forms are called cases (падежи́), and there are six: nominative, genitive, dative, accusative, instrumental and prepositional. English does this only with pronouns (he → him → his); Russian does it with every noun.","The prepositional case (предло́жный паде́ж) answers где? (where?) after в (in) and на (on). For most nouns the ending is -е: дом → в до́ме, Москва́ → в Москве́, шко́ла → в шко́ле.","Nouns in -ия take -ии: Росси́я → в Росси́и. Feminine nouns in -ь take -и: тетра́дь → в тетра́ди (in the notebook).","в means \"in(side)\" and на means \"on\". But some words always take на, much like English \"at\": на рабо́те (at work), на у́лице (outside, in the street), на по́чте (at the post office). Learn these with the word.","The same case follows о (about): Мы говори́м о ма́ме — We are talking about mum."]},"table":{"head":{"he":["צורת היסוד","איפה? (где?)"],"en":["Basic form","Where? (где?)"]},"rows":[["дом","в до́ме"],["Москва́","в Москве́"],["шко́ла","в шко́ле"],["стол","на столе́"],["Росси́я","в Росси́и"],["Изра́иль","в Изра́иле"],["рабо́та","на рабо́те"],["у́лица","на у́лице"]]},"examples":[{"t":"Я живу́ в Изра́иле.","p":{"he":"יא ז׳יוו ויזראילי.","en":"Ya zhivú v Izráile."},"m":{"he":"אני גר בישראל.","en":"I live in Israel."}},{"t":"Мой брат живёт в Москве́.","p":{"he":"מוי בראט ז׳יוויוט ומסקווה.","en":"Moy brat zhivyót v Moskvé."},"m":{"he":"אחי גר במוסקבה.","en":"My brother lives in Moscow."}},{"t":"Ма́ма на рабо́те.","p":{"he":"מאמא נא רבוטי.","en":"Máma na rabóte."},"m":{"he":"אמא בעבודה.","en":"Mum is at work."}},{"t":"Кни́га на столе́.","p":{"he":"קניגא נא סטלה.","en":"Kníga na stolé."},"m":{"he":"הספר על השולחן.","en":"The book is on the table."}},{"t":"Де́ти в шко́ле.","p":{"he":"דטי פשקולי.","en":"Déti v shkóle."},"m":{"he":"הילדים בבית הספר.","en":"The children are at school."}},{"t":"Мы бы́ли в теа́тре.","p":{"he":"מי בילי פטיאטרי.","en":"My býli v teátre."},"m":{"he":"היינו בתיאטרון.","en":"We were at the theatre."}},{"t":"Где ты? — Я в магази́не.","p":{"he":"גדה טי? — יא ומגזיני.","en":"Gde ty? — Ya v magazíne."},"m":{"he":"איפה אתה? — אני בחנות.","en":"Where are you? — I am in the shop."}},{"t":"Мы говори́м о ма́ме.","p":{"he":"מי גוורים א מאמי.","en":"My govorím o máme."},"m":{"he":"אנחנו מדברים על אמא.","en":"We are talking about mum."}}],"quiz":[{"q":{"he":"Я живу́ в ___. (Москва́)","en":"Я живу́ в ___. (Москва́)"},"opts":["Москву́","Москве́","Москва́","Москвы́"],"a":1,"why":{"he":"где? → ‎-е: в Москве́.","en":"где? → -е: в Москве́."}},{"q":{"he":"Па́па на ___. (рабо́та)","en":"Па́па на ___. (рабо́та)"},"opts":["рабо́ту","рабо́та","рабо́ты","рабо́те"],"a":3,"why":{"he":"איפה? → на рабо́те.","en":"Where? → на рабо́те."}},{"q":{"he":"Кни́га на ___. (стол)","en":"Кни́га на ___. (стол)"},"opts":["стол","стола́","столе́","столу́"],"a":2,"why":{"he":"стол → на столе́ (ההטעמה על הסיומת).","en":"стол → на столе́ (stress on the ending)."}},{"q":{"he":"Они́ живу́т в ___. (Росси́я)","en":"Они́ живу́т в ___. (Росси́я)"},"opts":["Росси́и","Росси́е","Росси́ю","Росси́я"],"a":0,"why":{"he":"‎-ия → ‎-ии: в Росси́и.","en":"-ия → -ии: в Росси́и."}},{"q":{"he":"איזו מילת יחס: ___ у́лице (ברחוב)","en":"Which preposition: ___ у́лице (in the street)"},"opts":["у","на","в","о"],"a":1,"why":{"he":"у́лица הולכת עם на: на у́лице.","en":"у́лица takes на: на у́лице."}},{"q":{"he":"כמה יחסות יש ברוסית?","en":"How many cases does Russian have?"},"opts":["шесть","де́сять","три","четы́ре"],"a":0,"why":{"he":"שש יחסות (шесть).","en":"Six cases (шесть)."}},{"q":{"he":"על איזו שאלה עונה в до́ме?","en":"Which question does в до́ме answer?"},"opts":["кто?","куда́?","где?","когда́?"],"a":2,"why":{"he":"יחסת המקום עונה על где? (איפה?).","en":"The prepositional answers где? (where?)."}},{"q":{"he":"Мы говори́м о ___. (ма́ма)","en":"Мы говори́м о ___. (ма́ма)"},"opts":["ма́му","ма́мы","ма́ма","ма́ме"],"a":3,"why":{"he":"о + יחסת המקום: о ма́ме.","en":"о + prepositional: о ма́ме."}}]},{"id":"accusative","level":"A2","title":{"he":"יחסת המושא: я ви́жу ма́му","en":"Accusative: я ви́жу ма́му"},"text":{"he":["יחסת המושא (вини́тельный паде́ж) מסמנת את המושא הישיר — את מה שרואים, קוראים, אוהבים. בעברית שמים \"את\" לפני מושא מיודע. ברוסית אין מילה כזאת, אבל סוף המילה משתנה — בכל מושא, מיודע או לא.","בנקבה ‎-а הופכת ל-‎-у, ו-‎-я ל-‎-ю: ма́ма → Я ви́жу ма́му (אני רואה את אמא), кни́га → Я чита́ю кни́гу. מילים בנקבה על ‎-ь לא משתנות: ночь → ночь.","בזכר ובסתמי, חפצים לא משתנים: Я ви́жу стол, Я ви́жу окно́. אבל זכר חי (אנשים ובעלי חיים) מקבל ‎-а או ‎-я: брат → Я ви́жу бра́та, учи́тель → Я ви́жу учи́теля.","כינויי הגוף: меня́ (אותי), тебя́ (אותך), его́ (אותו), её (אותה), нас (אותנו), вас (אתכם), их (אותם). Я люблю́ тебя́ — אני אוהב אותך. אותה יחסה באה גם אחרי в ו-на בתשובה ל-куда́? (לאן?): Я иду́ в шко́лу."],"en":["The accusative case (вини́тельный паде́ж) marks the direct object — what you see, read or love. English shows this only in pronouns (I see him); Russian changes many nouns too.","Feminine -а becomes -у, and -я becomes -ю: ма́ма → Я ви́жу ма́му (I see mum), кни́га → Я чита́ю кни́гу. Feminine nouns in -ь do not change: ночь → ночь.","Masculine and neuter things do not change: Я ви́жу стол, Я ви́жу окно́. But masculine people and animals take -а or -я: брат → Я ви́жу бра́та, учи́тель → Я ви́жу учи́теля.","Pronouns: меня́ (me), тебя́ (you), его́ (him), её (her), нас (us), вас (you), их (them). Я люблю́ тебя́ — I love you. The accusative also follows в and на for direction, answering куда́? (where to?): Я иду́ в шко́лу."]},"table":{"head":{"he":["מי? מה?","Я ви́жу… (אני רואה…)"],"en":["Who? What?","Я ви́жу… (I see…)"]},"rows":[["ма́ма","ма́му"],["кни́га","кни́гу"],["Ка́тя","Ка́тю"],["ночь","ночь"],["стол","стол"],["окно́","окно́"],["брат","бра́та"],["учи́тель","учи́теля"]]},"examples":[{"t":"Я ви́жу ма́му.","p":{"he":"יא ויז׳ו מאמו.","en":"Ya vízhu mámu."},"m":{"he":"אני רואה את אמא.","en":"I see mum."}},{"t":"Я чита́ю кни́гу.","p":{"he":"יא צ׳יטאיו קניגו.","en":"Ya chitáyu knígu."},"m":{"he":"אני קורא ספר.","en":"I am reading a book."}},{"t":"Ты зна́ешь А́нну?","p":{"he":"טי זנאיש אנו?","en":"Ty znáyesh Ánnu?"},"m":{"he":"אתה מכיר את אנה?","en":"Do you know Anna?"}},{"t":"Я ви́жу бра́та.","p":{"he":"יא ויז׳ו בראטא.","en":"Ya vízhu bráta."},"m":{"he":"אני רואה את אחי.","en":"I see my brother."}},{"t":"Мы лю́бим наш го́род.","p":{"he":"מי ליובים נאש גורט.","en":"My lyúbim nash górod."},"m":{"he":"אנחנו אוהבים את העיר שלנו.","en":"We love our city."}},{"t":"Она́ пьёт во́ду.","p":{"he":"אנא פיוט וודו.","en":"Oná pyot vódu."},"m":{"he":"היא שותה מים.","en":"She is drinking water."}},{"t":"Я люблю́ тебя́.","p":{"he":"יא ליובליו טיביא.","en":"Ya lyublyú tebyá."},"m":{"he":"אני אוהב אותך.","en":"I love you."}},{"t":"Мы идём в шко́лу.","p":{"he":"מי אידיום פשקולו.","en":"My idyóm v shkólu."},"m":{"he":"אנחנו הולכים לבית הספר.","en":"We are going to school."}}],"quiz":[{"q":{"he":"Я ви́жу ___. (ма́ма)","en":"Я ви́жу ___. (ма́ма)"},"opts":["ма́мой","ма́му","ма́ме","ма́ма"],"a":1,"why":{"he":"נקבה ‎-а → ‎-у.","en":"Feminine -а → -у."}},{"q":{"he":"Я чита́ю ___. (газе́та)","en":"Я чита́ю ___. (газе́та — newspaper)"},"opts":["газе́те","газе́ты","газе́та","газе́ту"],"a":3,"why":{"he":"газе́та → газе́ту.","en":"газе́та → газе́ту."}},{"q":{"he":"Я ви́жу ___. (брат)","en":"Я ви́жу ___. (брат)"},"opts":["бра́та","бра́ту","бра́те","брат"],"a":0,"why":{"he":"זכר חי → ‎-а: бра́та.","en":"Masculine animate → -а: бра́та."}},{"q":{"he":"Я ви́жу ___. (дом)","en":"Я ви́жу ___. (дом)"},"opts":["до́му","дом","до́ма","до́ме"],"a":1,"why":{"he":"חפץ בזכר לא משתנה: дом.","en":"A masculine thing does not change: дом."}},{"q":{"he":"Она́ лю́бит ___. (он)","en":"Она́ лю́бит ___. (он)"},"opts":["он","ему́","его́","им"],"a":2,"why":{"he":"он → его́ (אותו).","en":"он → его́ (him)."}},{"q":{"he":"Я зна́ю ___. (Ка́тя)","en":"Я зна́ю ___. (Ка́тя)"},"opts":["Ка́ти","Ка́те","Ка́тя","Ка́тю"],"a":3,"why":{"he":"‎-я → ‎-ю: Ка́тю.","en":"-я → -ю: Ка́тю."}},{"q":{"he":"Ты ___ ви́дишь? (я)","en":"Ты ___ ви́дишь? (я) — Can you see me?"},"opts":["меня́","мне","я","мной"],"a":0,"why":{"he":"я → меня́ (אותי).","en":"я → меня́ (me)."}},{"q":{"he":"Мы идём в ___. (шко́ла)","en":"Мы идём в ___. (шко́ла)"},"opts":["шко́лы","шко́ле","шко́лу","шко́ла"],"a":2,"why":{"he":"לאן? → יחסת המושא: в шко́лу.","en":"Where to? → accusative: в шко́лу."}}]},{"id":"genitive","level":"A2","title":{"he":"יחסת הקניין: нет, \"של\" ומספרים","en":"Genitive: нет, \"of\" and numbers"},"text":{"he":["יחסת הקניין (роди́тельный паде́ж) היא אחת השימושיות ביותר. הסיומות הבסיסיות: זכר וסתמי — ‎-а או ‎-я (брат → бра́та, окно́ → окна́), נקבה — ‎-ы או ‎-и (ма́ма → ма́мы, кни́га → кни́ги).","\"של\": הבעלים בא אחרי הדבר, ביחסת הקניין — כמו סמיכות בעברית: маши́на бра́та — המכונית של אחי.","\"אין\": אחרי нет באה תמיד יחסת הקניין: Здесь нет воды́ — אין כאן מים. У меня́ нет бра́та — אין לי אח.","מספרים: בעברית אחרי כל מספר בא רבים. ברוסית יש שלוש אפשרויות: אחרי 1 — צורת היסוד (оди́н стол); אחרי 2, 3, 4 — יחסת הקניין ביחיד (два стола́); מ-5 עד 20 — יחסת הקניין ברבים (пять столо́в). את הצורה של 5+ כדאי ללמוד עם כל מילה. (ב-21 שוב כמו ב-1, ב-22–24 כמו ב-2–4.)","גם 1 ו-2 משתנים לפי מין: оди́н стол אבל одна́ кни́га; два стола́ אבל две кни́ги."],"en":["The genitive case (роди́тельный паде́ж) is one of the most used. Basic endings: masculine and neuter -а or -я (брат → бра́та, окно́ → окна́), feminine -ы or -и (ма́ма → ма́мы, кни́га → кни́ги).","\"Of\" and possession: the owner comes after the thing, in the genitive: маши́на бра́та — my brother's car (literally \"car of brother\").","\"There is no\": after нет always use the genitive: Здесь нет воды́ — There is no water here. У меня́ нет бра́та — I don't have a brother.","Numbers: English has two forms (1 book, 2 books); Russian has three. After 1 — the basic form (оди́н стол); after 2, 3, 4 — genitive singular (два стола́); from 5 to 20 — genitive plural (пять столо́в). Learn the 5+ form with each word. (21 works like 1 again, 22–24 like 2–4.)","1 and 2 also change for gender: оди́н стол but одна́ кни́га; два стола́ but две кни́ги."]},"table":{"head":{"he":["1","2–4","5–20"],"en":["1","2–4","5–20"]},"rows":[["оди́н стол","два стола́","пять столо́в"],["одна́ кни́га","две кни́ги","пять книг"],["оди́н брат","три бра́та","пять бра́тьев"],["оди́н год","два го́да","пять лет"],["оди́н рубль","четы́ре рубля́","пять рубле́й"]]},"examples":[{"t":"У меня́ нет бра́та.","p":{"he":"או מיניא נט בראטא.","en":"U menyá net bráta."},"m":{"he":"אין לי אח.","en":"I don't have a brother."}},{"t":"Здесь нет воды́.","p":{"he":"זדס נט ודי.","en":"Zdes net vodý."},"m":{"he":"אין כאן מים.","en":"There is no water here."}},{"t":"Э́то маши́на бра́та.","p":{"he":"אטא משינא בראטא.","en":"Éto mashína bráta."},"m":{"he":"זו המכונית של אחי.","en":"This is my brother's car."}},{"t":"У меня́ две сестры́.","p":{"he":"או מיניא דווה סיסטרי.","en":"U menyá dve sestrý."},"m":{"he":"יש לי שתי אחיות.","en":"I have two sisters."}},{"t":"У нас три ко́мнаты.","p":{"he":"או נאס טרי קומנטי.","en":"U nas tri kómnaty."},"m":{"he":"יש לנו שלושה חדרים.","en":"We have three rooms."}},{"t":"Э́то сто́ит пять рубле́й.","p":{"he":"אטא סטויט פיאט רובליי.","en":"Éto stóit pyat rubléy."},"m":{"he":"זה עולה חמישה רובל.","en":"This costs five roubles."}},{"t":"Я живу́ здесь два го́да.","p":{"he":"יא ז׳יוו זדס דווא גודא.","en":"Ya zhivú zdes dva góda."},"m":{"he":"אני גר כאן שנתיים.","en":"I have lived here for two years."}},{"t":"Сего́дня нет уро́ка.","p":{"he":"סיוודניא נט אורוקא.","en":"Sevódnya net uróka."},"m":{"he":"היום אין שיעור.","en":"There is no lesson today."}}],"quiz":[{"q":{"he":"У меня́ нет ___. (маши́на)","en":"У меня́ нет ___. (маши́на)"},"opts":["маши́не","маши́ну","маши́ны","маши́на"],"a":2,"why":{"he":"нет + יחסת הקניין: маши́ны.","en":"нет + genitive: маши́ны."}},{"q":{"he":"два ___ (стол)","en":"два ___ (стол)"},"opts":["столо́в","стола́","стол","столы́"],"a":1,"why":{"he":"אחרי 2–4 — יחסת הקניין ביחיד: стола́.","en":"After 2–4 — genitive singular: стола́."}},{"q":{"he":"пять ___ (кни́га)","en":"пять ___ (кни́га)"},"opts":["кни́гу","книг","кни́га","кни́ги"],"a":1,"why":{"he":"מ-5 — יחסת הקניין ברבים: книг.","en":"From 5 — genitive plural: книг."}},{"q":{"he":"три ___ (год)","en":"три ___ (год — year)"},"opts":["го́ду","лет","го́да","год"],"a":2,"why":{"he":"2–4 → го́да; 5+ → лет.","en":"2–4 → го́да; 5+ → лет."}},{"q":{"he":"___ кни́ги (2)","en":"___ кни́ги (2 books)"},"opts":["два","пять","оди́н","две"],"a":3,"why":{"he":"кни́га נקבה → две.","en":"кни́га is feminine → две."}},{"q":{"he":"Здесь нет ___. (хлеб)","en":"Здесь нет ___. (хлеб — bread)"},"opts":["хле́ба","хлеб","хле́бу","хле́бе"],"a":0,"why":{"he":"нет + יחסת הקניין: хле́ба.","en":"нет + genitive: хле́ба."}},{"q":{"he":"איך אומרים \"המכונית של אחי\"?","en":"How do you say \"my brother's car\"?"},"opts":["маши́на бра́та","маши́на бра́ту","маши́на брат","маши́на бра́том"],"a":0,"why":{"he":"הבעלים ביחסת הקניין, אחרי הדבר: маши́на бра́та.","en":"The owner goes after, in the genitive: маши́на бра́та."}},{"q":{"he":"пять ___ (рубль)","en":"пять ___ (рубль — rouble)"},"opts":["рубли́","рубля́","рубль","рубле́й"],"a":3,"why":{"he":"5+ → רבים: рубле́й.","en":"5+ → genitive plural: рубле́й."}}]},{"id":"aspect_future","level":"A2","title":{"he":"אספקט (גמור / לא גמור) ועתיד","en":"Aspect (perfective / imperfective) and the future"},"text":{"he":["לרוב הפעלים ברוסית יש זוג: צורה \"לא גמורה\" (несоверше́нный вид) וצורה \"גמורה\" (соверше́нный вид). הלא גמורה — לתהליך, לפעולה שחוזרת, או לפעולה באופן כללי. הגמורה — לפעולה אחת שהושלמה ויש לה תוצאה.","לעתים קרובות הצורה הגמורה נוצרת בעזרת תחילית: де́лать → сде́лать, чита́ть → прочита́ть, писа́ть → написа́ть. לפעמים זו מילה אחרת: говори́ть → сказа́ть, покупа́ть → купи́ть.","בעבר: Я чита́л кни́гу — קראתי ספר (עסקתי בקריאה). Я прочита́л кни́гу — קראתי את הספר (עד הסוף). בעברית יש רק \"קראתי\", ברוסית צריך לבחור.","עתיד מהצורה הלא גמורה: бу́ду + מקור: Я бу́ду рабо́тать — אעבוד. הנטייה: бу́ду, бу́дешь, бу́дет, бу́дем, бу́дете, бу́дут.","עתיד מהצורה הגמורה: מטים אותה כמו הווה, והמשמעות היא עתיד: Я прочита́ю — אקרא (עד הסוף), Я куплю́ хлеб — אקנה לחם. לצורה הגמורה אין הווה."],"en":["Most Russian verbs come in pairs: imperfective (несоверше́нный вид) and perfective (соверше́нный вид). The imperfective is for a process, a repeated action, or the activity in general. The perfective is for one completed action with a result.","Often the perfective adds a prefix: де́лать → сде́лать, чита́ть → прочита́ть, писа́ть → написа́ть. Sometimes it is a different word: говори́ть → сказа́ть, покупа́ть → купи́ть.","In the past: Я чита́л кни́гу — I was reading / I read a book (the activity). Я прочита́л кни́гу — I read the book to the end. It is close to English \"was reading\" vs \"have read\".","Future of imperfective verbs: бу́ду + infinitive: Я бу́ду рабо́тать — I will work / I will be working. бу́ду changes like this: бу́ду, бу́дешь, бу́дет, бу́дем, бу́дете, бу́дут.","Future of perfective verbs: conjugate them like the present — the meaning is future: Я прочита́ю — I will read it (to the end), Я куплю́ хлеб — I will buy bread. Perfective verbs have no present tense."]},"table":{"head":{"he":["לא גמור","גמור","פירוש"],"en":["Imperfective","Perfective","Meaning"]},"rows":[["де́лать","сде́лать",{"he":"לעשות","en":"do"}],["чита́ть","прочита́ть",{"he":"לקרוא","en":"read"}],["писа́ть","написа́ть",{"he":"לכתוב","en":"write"}],["покупа́ть","купи́ть",{"he":"לקנות","en":"buy"}],["говори́ть","сказа́ть",{"he":"לומר, להגיד","en":"say, tell"}],["смотре́ть","посмотре́ть",{"he":"לצפות, להסתכל","en":"watch, look"}]]},"examples":[{"t":"Вчера́ я весь ве́чер чита́л.","p":{"he":"פצ׳ירא יא וס וצ׳יר צ׳יטאל.","en":"Vcherá ya ves vécher chitál."},"m":{"he":"אתמול קראתי כל הערב. (גבר)","en":"Yesterday I was reading all evening. (a man)"}},{"t":"Я уже́ прочита́л э́ту кни́гу.","p":{"he":"יא אוז׳ה פרצ׳יטאל אטו קניגו.","en":"Ya uzhé prochitál étu knígu."},"m":{"he":"כבר קראתי את הספר הזה. (גבר)","en":"I have already read this book. (a man)"}},{"t":"За́втра я бу́ду рабо́тать.","p":{"he":"זאפטרא יא בודו רבוטט.","en":"Závtra ya búdu rabótat."},"m":{"he":"מחר אעבוד.","en":"Tomorrow I will be working."}},{"t":"Я напишу́ письмо́ за́втра.","p":{"he":"יא נפישו פיסמו זאפטרא.","en":"Ya napishú pismó závtra."},"m":{"he":"אכתוב את המכתב מחר.","en":"I will write the letter tomorrow."}},{"t":"Что ты бу́дешь де́лать?","p":{"he":"שטו טי בודיש דלט?","en":"Shto ty búdesh délat?"},"m":{"he":"מה תעשה?","en":"What will you do?"}},{"t":"Мы ку́пим хлеб.","p":{"he":"מי קופים חלפ.","en":"My kúpim khleb."},"m":{"he":"נקנה לחם.","en":"We will buy bread."}},{"t":"Ка́ждый день я покупа́ю хлеб.","p":{"he":"קאז׳די דן יא פקופאיו חלפ.","en":"Kázhdyy den ya pokupáyu khleb."},"m":{"he":"כל יום אני קונה לחם.","en":"I buy bread every day."}},{"t":"Она́ сказа́ла «да».","p":{"he":"אנא סקזאלא \"דא\".","en":"Oná skazála \"da\"."},"m":{"he":"היא אמרה \"כן\".","en":"She said \"yes\"."}}],"quiz":[{"q":{"he":"За́втра я ___ рабо́тать.","en":"За́втра я ___ рабо́тать. (Tomorrow I will work.)"},"opts":["был","есть","бу́дет","бу́ду"],"a":3,"why":{"he":"עתיד לא גמור: я бу́ду + מקור.","en":"Imperfective future: я бу́ду + infinitive."}},{"q":{"he":"הצורה הלא גמורה של купи́ть:","en":"The imperfective partner of купи́ть:"},"opts":["покупа́ть","покупи́ть","купа́ть","скупи́ть"],"a":0,"why":{"he":"купи́ть / покупа́ть — זוג.","en":"купи́ть / покупа́ть are a pair."}},{"q":{"he":"Я уже́ ___ кни́гу. Вот она́! (סיימתי)","en":"Я уже́ ___ кни́гу. Вот она́! (finished)"},"opts":["бу́ду чита́ть","чита́ть","прочита́л","чита́ю"],"a":2,"why":{"he":"תוצאה גמורה בעבר → прочита́л.","en":"A finished result in the past → прочита́л."}},{"q":{"he":"Ка́ждый день он ___ газе́ту.","en":"Ка́ждый день он ___ газе́ту. (every day)"},"opts":["прочита́ет","чита́ет","прочита́ть","прочита́л"],"a":1,"why":{"he":"פעולה שחוזרת → לא גמור: чита́ет.","en":"A repeated action → imperfective: чита́ет."}},{"q":{"he":"За́втра я ___ письмо́. (גמור)","en":"За́втра я ___ письмо́. (perfective)"},"opts":["пишу́","написа́л","писа́л","напишу́"],"a":3,"why":{"he":"עתיד גמור: напишу́.","en":"Perfective future: напишу́."}},{"q":{"he":"איזה פועל הוא בצורה הגמורה?","en":"Which verb is perfective?"},"opts":["сде́лать","чита́ть","де́лать","говори́ть"],"a":0,"why":{"he":"сде́лать — גמור (עם התחילית с-).","en":"сде́лать — perfective (prefix с-)."}},{"q":{"he":"Мы ___ смотре́ть фильм.","en":"Мы ___ смотре́ть фильм. (We will watch a film.)"},"opts":["бу́ду","бу́дут","бу́дем","бу́дете"],"a":2,"why":{"he":"мы → бу́дем.","en":"мы → бу́дем."}},{"q":{"he":"איך אומרים \"אני אקנה\"?","en":"How do you say \"I will buy\"?"},"opts":["покупа́л","куплю́","купи́л","бу́ду купи́ть"],"a":1,"why":{"he":"עתיד גמור: куплю́. אי אפשר לומר бу́ду + פועל גמור.","en":"Perfective future: куплю́. бу́ду never goes with a perfective verb."}}]}]});
